config:
cards.@hooks [
	{
		func load
		files [
			{
				@func concat
				strings [
					{
						@func datadir
					}
					'/cards/aliases.conf'
				]
			}
		]
	}
	{
		func load_for_all_cards
		files [
			{
				@func concat
				strings [
					{
						@func datadir
					}
					/cards/
					{
						@func private_string
					}
					'.conf'
				]
			}
			{
				root {
					@func private_integer
				}
				file {
					@func concat
					strings [
						/var/lib/alsa/card
						{
							@func private_integer
						}
						'.conf.d'
					]
				}
			}
		]
		table {
			id {
				@func concat
				strings [
					{
						@func private_integer
					}
				]
			}
			value {
				@func concat
				strings [
					'cards.'
					{
						@func private_string
					}
				]
			}
		}
		errors false
	}
]
